async function findConnectedModel(agent) {
	const modelList = await agent.getModelList();
	if (modelList && modelList.length > 0) {
		for (const modelConfig of modelList) if (modelConfig.enabled !== false) {
			const model = modelConfig.model;
			if (isProviderConnected(model.provider)) return model;
		}
		return null;
	}
	const defaultModel = await agent.getModel();
	if (isProviderConnected(defaultModel.provider)) return defaultModel;
	return null;
}
